/**
 * "Michael's read" on a goal: a short observation and the questions worth
 * asking, computed by fixed rules from the goal's own saved fields. Nothing
 * here is generated by a model, so showing it spends no model turn; the
 * actions only prefill the assistant (or, for syncing progress, are an
 * ordinary progress update the user triggers).
 */
export type GoalCoachInput = {
  title: string;
  status: string;
  progress: number;
  targetDate: string | null;
  milestones: Array<{ title: string; status: string }>;
};

export type GoalCoachRead = {
  /** One or two sentences in Michael's voice. */
  text: string;
  /** The first pending milestone, when there is one. */
  nextMilestone: string | null;
  /** Percentage of milestones completed; null without milestones. */
  milestonePercent: number | null;
  targetPassed: boolean;
  /** Manual progress and milestone progress disagree by this many points or more. */
  progressDrift: boolean;
};

export const PROGRESS_DRIFT_POINTS = 10;

export function goalCoachRead(goal: GoalCoachInput, today: string): GoalCoachRead {
  const total = goal.milestones.length;
  const done = goal.milestones.filter((milestone) => milestone.status === "COMPLETED").length;
  const milestonePercent = total ? Math.round((done / total) * 100) : null;
  const nextMilestone = goal.milestones.find((milestone) => milestone.status !== "COMPLETED")?.title ?? null;
  const targetPassed = goal.status === "ACTIVE" && goal.targetDate !== null && goal.targetDate < today;
  const progressDrift = milestonePercent !== null && Math.abs(goal.progress - milestonePercent) >= PROGRESS_DRIFT_POINTS;

  const sentences: string[] = [];
  if (milestonePercent === null) sentences.push(`This goal has no milestones yet. Breaking it into a few steps makes progress easier to see.`);
  else if (progressDrift) sentences.push(`Your manual progress (${goal.progress}%) is ${goal.progress > milestonePercent ? "ahead of" : "behind"} your milestones (${milestonePercent}%).`);
  else sentences.push(`${done} of ${total} milestones are done, in step with your ${goal.progress}% progress.`);
  if (nextMilestone) sentences.push(`${nextMilestone} is the next step.`);
  else if (total > 0) sentences.push("Every milestone is complete.");
  if (targetPassed) sentences.push("The target date has passed, so it may be worth choosing a new one.");
  return { text: sentences.join(" "), nextMilestone, milestonePercent, targetPassed, progressDrift };
}
